thm-hyp(
    list-partial(
        Algebra.CommMonoid(G@Algebra.ctxt.G, $\cdot$@Algebra.ctxt.mul),
        Type.annotation(
            @$\sim$,
            Rl(Type.prod(G@Algebra.ctxt.G, G@Algebra.ctxt.G), Type.prod(G@Algebra.ctxt.G, G@Algebra.ctxt.G))
        ),
        def[predicate](
            Rl.apply($\sim$, Type.pair(@a, @b), Type.pair(@c, @d)),
            Logic.exists-typed(
                @m, 
                G@Algebra.ctxt.G,
                Eq(
                    Bop.apply($\cdot$@Algebra.ctxt.mul, Bop.apply($\cdot$@Algebra.ctxt.mul, a, b), m),
                    Bop.apply($\cdot$@Algebra.ctxt.mul, Bop.apply($\cdot$@Algebra.ctxt.mul, c, d), m)
                )
            )
        )
    ),
    Algebra.Abelian(quotient(Type.prod(G@Algebra.ctxt.G, G@Algebra.ctxt.G), $\sim$), $\cdot$@Algebra.ctxt.mul)
)
